CREATE OR REPLACE FUNCTION gf_bootstrap_user(p_privacy text, p_terms text) RETURNS json LANGUAGE sql SECURITY DEFINER SET search_path = public AS $body$ WITH ins AS (INSERT INTO users (identity_id) VALUES (auth.uid()) ON CONFLICT (identity_id) DO UPDATE SET last_login_at = now(), updated_at = now() RETURNING id, identity_id, nickname, avatar_url, (xmax = 0) AS is_new), c1 AS (INSERT INTO consent_records (user_id, policy_type, policy_version) SELECT auth.uid(), 'PRIVACY', p_privacy WHERE p_privacy IS NOT NULL AND p_privacy <> '' ON CONFLICT (user_id, policy_type, policy_version) DO NOTHING), c2 AS (INSERT INTO consent_records (user_id, policy_type, policy_version) SELECT auth.uid(), 'TERMS', p_terms WHERE p_terms IS NOT NULL AND p_terms <> '' ON CONFLICT (user_id, policy_type, policy_version) DO NOTHING) SELECT json_build_object('user', json_build_object('id', ins.id, 'nickname', ins.nickname, 'avatarUrl', ins.avatar_url, 'isNewUser', ins.is_new)) FROM ins $body$;